run_generated_snippet: doors = revit_ro.get_elements("Doors")
cols = revit_ro.get_elements("Columns")
col_pts = []
for c in cols:
    ln = revit_ro.get_line(c["id"])
    if ln != None and ln.get("point") != None:
        p = ln["point"]
        col_pts.append((p[0], p[1]))
    else:
        bb = revit_ro.get_geometry_bbox(c["id"])
        if bb != None:
            c0 = bb["center"]
            col_pts.append((c0[0], c0[1]))

within = []
R2 = 3.0 * 3.0
for d in doors:
    ln = revit_ro.get_line(d["id"])
    pt = None
    if ln != None and ln.get("point") != None:
        p = ln["point"]
        pt = (p[0], p[1])
    else:
        bb = revit_ro.get_geometry_bbox(d["id"])
        if bb != None:
            c0 = bb["center"]
            pt = (c0[0], c0[1])
    if pt == None:
        continue
    for cp in col_pts:
        dx = pt[0] - cp[0]
        dy = pt[1] - cp[1]
        if dx*dx + dy*dy <= R2:
            within.append(d["id"]) 
            break

result = {"count": len(within), "door_ids": within}

run_generated_snippet: rooms = revit_ro.get_elements("Rooms")
cols = revit_ro.get_elements("Columns")
output = []
for r in rooms:
    rb = revit_ro.get_geometry_bbox(r["id"])
    if rb == None:
        continue
    rmin = rb["min"]
    rmax = rb["max"]
    rlevel = revit_ro.get_level_of_element(r["id"])
    found = []
    for c in cols:
        cb = revit_ro.get_geometry_bbox(c["id"])
        if cb == None:
            # try point fallback
            line = revit_ro.get_line(c["id"])
            if line and "point" in line:
                ccenter = line["point"]
            else:
                continue
        else:
            ccenter = cb.get("center")
            if ccenter == None:
                line = revit_ro.get_line(c["id"])
                if line and "point" in line:
                    ccenter = line["point"]
                else:
                    continue
        clevel = revit_ro.get_level_of_element(c["id"])
        if rlevel != None and clevel != None and rlevel != clevel:
            continue
        x,y,z = ccenter[0], ccenter[1], ccenter[2]
        if x >= rmin[0] and x <= rmax[0] and y >= rmin[1] and y <= rmax[1] and z >= rmin[2] and z <= rmax[2]:
            found.append(c["id"])
    if found:
        output.append({"room_id": r["id"], "room_number": revit_ro.get_param(r["id"], "Number"), "room_name": revit_ro.get_param(r["id"], "Name"), "column_ids": found})
result = output

run_generated_snippet: cols = revit_ro.get_elements("Columns")
pts = []
for c in cols:
    ln = revit_ro.get_line(c["id"])
    if ln != None and ("point" in ln):
        p = ln["point"]
    else:
        bbox = revit_ro.get_geometry_bbox(c["id"])
        if bbox != None and ("center" in bbox):
            p = bbox["center"]
        else:
            p = None
    pts.append({"id": c["id"], "point": p})

max_sq = -1.0
pair = [None, None]
n = len(pts)
for i in range(n):
    pi = pts[i]["point"]
    if pi == None:
        continue
    for j in range(i+1, n):
        pj = pts[j]["point"]
        if pj == None:
            continue
        dx = pi[0] - pj[0]
        dy = pi[1] - pj[1]
        dz = pi[2] - pj[2]
        s = dx*dx + dy*dy + dz*dz
        if s > max_sq:
            max_sq = s
            pair = [pts[i]["id"], pts[j]["id"]]

if max_sq < 0:
    result = {"error": "Not enough column points available to compute distance", "count_columns": len(cols)}
else:
    # compute sqrt of max_sq using Newton iterations
    x = max_sq
    if x == 0:
        dist = 0.0
    else:
        g = x if x >= 1.0 else 1.0
        for k in range(20):
            g = 0.5*(g + x/g)
        dist = g
    result = {"distance_m": round(dist, 3), "column_id_pair": pair, "distance_squared_m2": round(max_sq, 6)}
